import java.util.Comparator;

public class PopulationSorter implements Comparator<Population> {
    @Override
    public int compare(Population p1, Population p2) {
        // First, compare by expected population in descending order
        int expectedCompare = Integer.compare(p2.getExpectedPopulation(), p1.getExpectedPopulation());
        if (expectedCompare != 0) {
            return expectedCompare;
        }

        // If expected populations are equal, compare by actual population in descending order
        int actualCompare = Integer.compare(p2.getActualPopulation(), p1.getActualPopulation());
        if (actualCompare != 0) {
            return actualCompare;
        }

        // If both populations are equal, compare by year in ascending order
