public class PdfConverter
{
    public static string ConvertPdfToBase64(string filePath)
    {
        // 1. Check if the file exists to avoid FileNotFoundException
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("The specified PDF file was not found.", filePath);
        }

        // 2. Read the PDF file into a byte array
        byte[] pdfBytes = File.ReadAllBytes(filePath);

        // 3. Convert the byte array to a Base64 string
        // Using the default overload ensures no line breaks are inserted,
        // which is crucial for JSON payload compatibility.
        string base64String = Convert.ToBase64String(pdfBytes);

        return base64String;
    }
}
